package com.arjunren.leave.config;
import com.arjunren.leave.domain.Role;import com.arjunren.leave.entity.*;import com.arjunren.leave.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;
@Component@Profile("dev")public class DevDataSeeder implements CommandLineRunner{private final UserRepository users;private final EmployeeProfileRepository employees;private final PasswordEncoder encoder;public DevDataSeeder(UserRepository u,EmployeeProfileRepository e,PasswordEncoder p){users=u;employees=e;encoder=p;}public void run(String...args){var manager=seedUser("manager@example.com","Development Manager","ManagerPassword123!",Role.MANAGER);var employee=seedUser("employee@example.com","Development Employee","EmployeePassword123!",Role.EMPLOYEE);seedUser("admin@example.com","Development Admin","AdminPassword123!",Role.ADMIN);seedProfile("MGR-001",manager,null,"Engineering");seedProfile("EMP-001",employee,manager,"Engineering");}private AppUser seedUser(String email,String name,String pass,Role role){return users.findByEmailIgnoreCase(email).orElseGet(()->users.save(new AppUser(email,encoder.encode(pass),name,role)));}private void seedProfile(String n,AppUser u,AppUser m,String d){if(employees.findByUserId(u.getId()).isEmpty())employees.save(new EmployeeProfile(n,u,m,d,20,10));}}

